export function uniqueBy(items, keyFn) {
  if (!Array.isArray(items) || typeof keyFn !== 'function') throw new TypeError('Expected an array and a function');
  const seen = new Set();
  return items.filter((item, index) => {
    const key = keyFn(item, index);
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}
